import { Container } from "react-bootstrap";

export const Education = () => {

  const education = [
    { institute: "Acharya Institute of Technology", degree: "MCA", year: "2025 – 2027", status: "Currently Pursuing" },
    { institute: "KLE Society’s BCA College", degree: "Bachelor of Computer Applications", year: "2022 – 2025" },
    { institute: "Sai Niketan PU Science College", degree: "PUC – Science", year: "2020 – 2022" },
    { institute: "Swami Vivekanand International Public School (CBSE)", degree: "Schooling", year: "2009 – 2020" }
  ];

  return (
    <section className="education" id="education">
      <Container>
        <div className="education-bx">
          <h2>Education</h2>
          <p>My academic journey built with dedication, innovation and futuristic learning 🌌</p>

          <div className="edu-grid">
            {education.map((edu, index) => (
              <div className="edu-card" key={index}>
                <h4>{edu.institute}</h4>
                <h6>{edu.degree}</h6>
                <span>{edu.year}</span>
                {edu.status && <p className="edu-status">{edu.status}</p>}
              </div>
            ))}
          </div>
        </div>
      </Container>
    </section>
  );
};
